#!/usr/bin/env bash
# Self-contained CSS для plan-checkup/bento-round (bash-only, без PowerShell).
set -euo pipefail

ROUND="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PARENT="$(cd "$ROUND/.." && pwd)"
OUT="$ROUND/lab-base.css"

# тема «Бенто» (токены plan-web) + этот раунд
sources=(
  "$PARENT/styles.css"
  "$ROUND/styles.css"
)

{
  cat <<'EOF'
/* Auto-generated by sync-lab.sh - do not edit by hand */
/* Round: plan-checkup/bento-round */
/* Sources: ../styles.css, styles.css */

EOF
  for src in "${sources[@]}"; do
    if [[ ! -f "$src" ]]; then
      echo "sync-lab.sh: missing source: $src" >&2
      exit 1
    fi
    cat "$src"
    printf '\n'
  done
} > "$OUT"

echo "OK: $OUT"
